// Changes: Pure toast stack – toasts stack instead of replacing each other, errors stay until dismissed,
//          and the announcement carries only the visible text (+ a hint when actions are available).

export type ToastTone = 'ok' | 'bad' | 'info'

export interface ToastOptions {
  title: string
  description?: string
  tone?: ToastTone
  /** Auto-dismiss delay in ms for non-error toasts; error toasts always stay until dismissed. */
  duration?: number
  actionLabel?: string
  onAction?: () => void
}

export interface ToastItem extends Omit<ToastOptions, 'tone' | 'duration'> {
  id: number
  tone: ToastTone
  /** null = stays until the user dismisses it. */
  duration: number | null
}

export const DEFAULT_DURATION = 5000
export const MAX_TOASTS = 4

const TONE_PREFIX: Record<ToastTone, string> = { bad: 'Chyba: ', ok: '', info: '' }

export function addToast(stack: ToastItem[], options: ToastOptions, id: number, max = MAX_TOASTS): ToastItem[] {
  const tone = options.tone ?? 'info'
  const item: ToastItem = { ...options, id, tone, duration: tone === 'bad' ? null : (options.duration ?? DEFAULT_DURATION) }
  const next = [...stack, item]
  while (next.length > max) {
    const timed = next.findIndex((t) => t.duration !== null)
    next.splice(timed === -1 ? 0 : timed, 1)
  }
  return next
}

export const dismissToast = (stack: ToastItem[], id: number) => stack.filter((t) => t.id !== id)

export function toastAnnouncement(t: ToastItem) {
  const text = `${TONE_PREFIX[t.tone]}${t.title}${t.description ? `. ${t.description}` : ''}`
  return t.actionLabel && t.onAction ? `${text}. Akcie sú dostupné.` : text
}
